+/// Which axis a unit normal stands along, within the tolerance: 0, 1
+/// or 2 for X, Y, Z, and its sign.
+pub(super) fn axis_of(n: Point3) -> Option<(usize, f64)> {
+    let cos = PROBE_AXIS_TOL_DEG.to_radians().cos();
+    [n.x, n.y, n.z]
+        .into_iter()
+        .enumerate()
+        .find(|(_, c)| c.abs() >= cos)
+        .map(|(k, c)| (k, c.signum()))
