+
+/// The op page's account of a probe's pick: the seed it made, or why
+/// it makes none. `None` for other kinds.
+#[must_use]
+pub fn probe_account(world: &World, items: &[GeoSel], params: &OpParams) -> Option<(Vec<String>, Option<String>)> {
