+const MIN_AXES_ANGLE_DEG: f64 = 1.0;
+/// Two picked points closer than this (mm) are one point.
+const COINCIDENT_MM: f64 = 1e-3;
+/// The turned direction must land on its axis this closely (sine).
+const LAND_TOL: f64 = 1e-9;
