+/// Which in-plane axis a pick sets.
+#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
+pub enum InPlaneAxis {
+    #[default]
+    Y,
+    X,
+}
+
+impl InPlaneAxis {
+    #[must_use]
+    pub fn label(self) -> &'static str {
+        match self {
+            InPlaneAxis::Y => "+Y",
+            InPlaneAxis::X => "+X",
+        }
