+
+fn unit(a: [f64; 3]) -> Option<[f64; 3]> {
+    let l = norm(a);
+    (l.is_finite() && l > 0.0).then(|| scale(a, 1.0 / l))
+}
+
+fn p3(a: [f64; 3]) -> Point3 {
+    Point3::new(a[0], a[1], a[2])
+}

