+impl ToolBodyDto {
+    #[must_use]
+    pub fn from_body(b: &ToolBody) -> Self {
+        let facets = facets_to_dto(&b.facets);
+        let spun = b.spun.as_ref().map(|s| s.points().iter().map(|p| [p.z, p.r, p.arc]).collect());
+        match &b.frame {
+            BodyFrame::Spindle { axis, offset, .. } => Self {
+                source: b.source.clone(),
+                axis: Some(*axis),
+                offset: Some(*offset),
+                lathe: None,
+                insert_zone: None,
+                facets,
+                spun,
