+/// Whether a block carries `code` as a word (Heidenhain ends its
+/// blocks with `*`, line numbers lead some dialects' blocks).
+fn has_word(line: &str, code: &str) -> bool {
+    line.split_whitespace().any(|w| w.trim_end_matches('*') == code)
+}
