+fn mch_with_x_direction(direction: &str) -> String {
+    format!(
+        r#"{{
+      "general": {{"model": "Flip 1", "vendor": "CamCraft Testbench", "kind": "mill"}},
+      "kinematics": {{"default": {{"units": {{"length": "mm"}}, "parts": [
