+fn post_text(world: &World, tag: &str) -> Result<String, String> {
+    let out = std::env::temp_dir().join(format!("camcraft_axisdir_{tag}_{}.nc", std::process::id()));
+    let r = posting::post_setup(world, &out).map(|p| p.program);
