+fn noted(world: &World) -> bool {
+    let notes = cached(world, "Contour2").path.notes;
+    notes.iter().any(|n| n.starts_with(CARRIED_OUTSIDE_DECLARED) && n.contains("'Setup1'") && n.contains("'Setup2'"))
+}
