+    operation::retype_params(&base, ty.ordinal())
+}
+
+fn brick(x0: f64) -> camcraft_app::geometry::Mesh {
+    cube(Point3::new(x0, -10.0, 0.0), Point3::new(x0 + 40.0, 10.0, 10.0))
