+        bar_load: false,
+        bar_advance: 0.0,
+        bar_unload: false,
+        bar_transfer: false,
+        inspect_tol: 0.0,
+    }
+}
+
+fn set_corner(world: &World, history: &mut History, q: Option<u8>) {
+    let e = model::find_by_name(world, GT).expect("tool");
