+        if self.kw("+") {
+            return self.unary(v);
+        }
+        self.primary(v)
+    }
+
+    fn primary(&mut self, v: &dyn Vars) -> Result<f64, String> {
+        if self.kw("[") {
+            let a = self.expr(v)?;
+            self.want("]")?;
+            return Ok(a);
+        }
+        if self.kw("ABS[") {
+            let a = self.expr(v)?;
+            self.want("]")?;
+            return Ok(a.abs());
+        }
+        if self.kw("#") {
+            let n = self.var_no(v)?;
+            return v.read(n);
+        }
+        self.num()
+    }
+
+    /// `a OP b` inside an `IF[ ]`.
+    pub fn cond(&mut self, v: &dyn Vars) -> Result<bool, String> {
+        let a = self.expr(v)?;
+        for (op, f) in [
+            ("EQ", (|a, b| a == b) as fn(f64, f64) -> bool),
+            ("NE", |a, b| a != b),
+            ("GT", |a, b| a > b),
+            ("LT", |a, b| a < b),
+            ("GE", |a, b| a >= b),
+            ("LE", |a, b| a <= b),
+        ] {
+            if self.kw(op) {
+                let b = self.expr(v)?;
+                return Ok(f(a, b));
+            }
+        }
+        Err(format!("expected a comparison at {:?}", self.rest()))
+    }
+}

