+/// A line's text with the dialect's block number stripped (`N20 `).
+fn body(line: &str) -> &str {
+    match line.strip_prefix('N').and_then(|r| r.split_once(' ')) {
+        Some((n, rest)) if n.chars().all(|c| c.is_ascii_digit()) => rest,
+        _ => line,
+    }
