+        let at = |s: &str| {
+            lines
+                .iter()
+                .position(|l| *l == s)
+                .unwrap_or_else(|| panic!("{stem}: no {s:?} in\n{nc}"))
+        };
+        let (s, o, t) = (at(notes[0]), at(notes[1]), at(notes[2]));
+        assert!(
+            s < o && o < t,
+            "{stem}: setup, then operation, then tool:\n{nc}"
+        );
