+        // run first, then the call).
+        assert!(
+            lines.iter().skip(t + 1).take(3).any(|l| l == tool_call),
+            "{stem}: the tool comment leads its tool call:\n{nc}"
+        );
+        let count = |s: &str| lines.iter().filter(|l| **l == s).count();
+        assert_eq!(
+            [count(notes[0]), count(notes[1]), count(notes[2])],
+            [1, 2, 2],
