+    let bad = old
+        .replace("\"version\": 50", &format!("\"version\": {}", project::PROJECT_VERSION))
+        .replace("\"wcs\": [\"G54\", \"G55\"]", "\"wcs\": \"G54\", \"work_offset\": \"G60\"");
+    let err = project::open(&new_world(), &bad).expect_err("G60 is no slot");
