+const TOP: f64 = 20.0;
+const BOTTOM: f64 = -10.0;
+/// 12 mm deep: inside the catalog tap's 20 mm flute, so the reach law
+/// (a shank wider than the hole) never enters.
+const HOLE_FLOOR: f64 = 8.0;
