+        top_z: Height::fixed(TOP),
+        bottom_z: None,
+        cycle: CycleChoice::Tap,
+        peck: 0.0,
+        dwell: 0.0,
+        feed: 600.0,
+        plunge_feed: 600.0,
+        holes: vec![hole(half_width)],
+        cross: vec![],
+    };
+    world_with_op(half_width, TAP, tool, params)
+}
