+/// `c_end`) as the station pose at C `c`: turned about Z by the turn
+/// left between them. At `c == c_end` the axis comes back unchanged,
+/// bit for bit.
+fn pose_at(axis: [f64; 3], c_end: f64, c: f64) -> [f64; 3] {
+    if c == c_end {
+        return axis;
+    }
+    let (s, co) = (c_end - c).to_radians().sin_cos();
