+    fn the_station_pose_is_read_from_c_and_other_paths_stay_borrowed() {
+        let plain = Toolpath::new(vec![Move::new(MoveKind::Feed, Point3::new(0.0, 0.0, 0.0), Point3::new(1.0, 0.0, 0.0), None)]);
