+/// the jaws and the holder (75 mm up) clears their tops at z 50.
+fn tool() -> ToolGeom {
+    ToolGeom {
+        radius: 4.0,
+        nose_radius: 0.0,
+        flute_len: 30.0,
+        shank_radius: 5.0,
+        shank_len: 20.0,
+        holder_radius: 20.0,
+        holder_len: 40.0,
