+    let body = HolderStack { bands: vec![HolderBand { above: 50.0, len: 40.0, r: 20.0 }], top: 90.0 };
+    assert_eq!(
+        rapids_vs_fixtures_held(&path, &slim, &body, &[bolt()], None),
+        hit(FixturePart::Holder),
+        "the body's r20 collar reaches the bolt"
+    );
+}
