+fn part(wall_x: f64, floor: bool) -> Vec<Triangle> {
+    let mut f = cube(p(wall_x, -10.0, 0.0), p(10.0, 10.0, WALL_TOP)).facets.to_vec();
+    if floor {
+        f.extend(cube(p(-10.0, -10.0, 0.0), p(10.0, 10.0, FLOOR)).facets.iter().copied());
