+    let labels: Vec<String> = rows(&h.state().state, RecentKind::Project).iter().map(|(r, _)| r.label()).collect();
+    assert_eq!(labels, ["gone.camproj (missing)", "b.camproj", "a.camproj", CLEAR, BROWSE], "newest first");
+    for label in &labels {
