+}
+
+#[test]
+fn a_missing_entry_is_refused_by_name() {
+    let d = temp_dir("missing");
+    let gone = d.join("gone.camproj");
+    let mut h = shell_harness();
+    h.state_mut().state.recent.add(RecentKind::Project, &gone);
