+    h.state_mut().state.pending.push_back(CommandKind::OpenRecent(RecentKind::Model, d.join("gone.stl")));
+    h.run_steps(2);
+    assert!(h.state().state.status.contains("gone.stl is missing"), "{}", h.state().state.status);
